 const issues=c.issues.length;b.innerHTML=`<div><b>${mine?(locationReadOnly||locationIsCached?"Approximate area":esc(areaName||"Your neighborhood")):"Selected neighborhood"}</b><div class="mute">This grid · ${c.th.length} thoughts · ${issues} issues · ${active} businesses${mine?(locationReadOnly||locationIsCached?" · read only":""):" · browsing only"}</div></div><button class="btn ${mine&&!locationReadOnly&&!locationIsCached?"p":""}" id="go">${mine?(locationReadOnly||locationIsCached?"Keep exploring":"Open neighborhood"):"Explore this grid"}</button>`;
