function adDest(a,id){if(a.lat!=null&&a.lon!=null)return `${a.lat},${a.lon}`;const[q,r]=id.split(",").map(Number),[x,y]=hexC(q,r);return `${(2*Math.atan(Math.exp(y/R0))-Math.PI/2)*180/Math.PI},${x/R0*180/Math.PI}`}
function adAvailable(a,now=new Date()){if(a.exp<=now.getTime())return false;if(!a.openTime||!a.closeTime)return !a.starts||a.starts<=now.getTime();const hm=now.toTimeString().slice(0,5);return a.openTime<=a.closeTime?(hm>=a.openTime&&hm<a.closeTime):(hm>=a.openTime||hm<a.closeTime)}
