let authClient=null,authPhone="",authResendTimer=null,realAuth=false;
function authMessage(id,message,ok=false){const e=$(id);e.textContent=message;e.classList.toggle("ok",ok)}
function phoneAuthConfigured(){const cfg=window.GRIDSPACE_AUTH_CONFIG||{};return !!(cfg.url&&cfg.publishableKey&&cfg.phoneAuthEnabled===true)}
function beginApp(isVerified,userId="preview"){const nextKey=isVerified?`gs2_user_${userId}`:"gs2";if($("#authgate").hidden&&realAuth===!!isVerified&&storageKey===nextKey)return;if(storageKey!==nextKey){storageKey=nextKey;S=readState(storageKey)}realAuth=!!isVerified;$("#account").hidden=!realAuth;$("#authgate").hidden=true;const invite=new URL(location.href).searchParams.get("grid");if(invite&&/^[-]?\d+,[-]?\d+$/.test(invite)){viewHex=invite;mode="list";tab="feed";started=1;locationReadOnly=true;optionalText("#city","Shared grid · read only");const intro=$("#intro");if(intro)intro.remove();loadLandMask();render();return}loadLandMask();ask()}
function showLogin(){started=0;$("#authgate").setAttribute("aria-labelledby","auth-title");if(storageKey!=="gs2"){storageKey="gs2";S=readState(storageKey)}$("#account").hidden=true;$("#authgate").hidden=false;$("#phone-step").hidden=false;$("#otp-step").hidden=true;$("#business-step").hidden=true;$("#preview-option").hidden=phoneAuthConfigured();(phoneAuthConfigured()?$("#phone-number"):$("#preview-continue")).focus()}
function setResendCooldown(seconds=60){clearInterval(authResendTimer);let left=seconds;const b=$("#resend-code");b.disabled=true;b.textContent=`Resend code in ${left}s`;authResendTimer=setInterval(()=>{left--;if(left<=0){clearInterval(authResendTimer);b.disabled=false;b.textContent="Resend code"}else b.textContent=`Resend code in ${left}s`},1000)}
function normalizePhone(){const cc=$("#country-code").value;let raw=$("#phone-number").value.replace(/[^0-9]/g,"");const dial=cc.slice(1);if(raw.startsWith(dial)&&raw.length>dial.length)raw=raw.slice(dial.length);if(cc==="+91"&&raw.startsWith("0")&&raw.length===11)raw=raw.slice(1);if(cc==="+91"&&raw.length!==10)throw Error("Enter a 10-digit Indian mobile number.");if(raw.length<7||raw.length>15)throw Error("Check the mobile number and try again.");return cc+raw}
async function sendPhoneCode(resend=false){authMessage(resend?"#otp-msg":"#auth-msg","");let phone;try{phone=resend?authPhone:normalizePhone()}catch(e){authMessage("#auth-msg",e.message);return}
 const b=$(resend?"#resend-code":"#send-code");b.disabled=true;if(!resend)b.textContent="Sending…";
 try{const {error}=await authClient.auth.signInWithOtp({phone});if(error)throw error;authPhone=phone;$("#authgate").setAttribute("aria-labelledby","otp-title");$("#otp-copy").textContent=`Enter the six-digit code sent to ${phone}.`;$("#phone-step").hidden=true;$("#otp-step").hidden=false;$("#otp-code").value="";$("#otp-code").focus();authMessage("#otp-msg","Code sent. Check your messages.",true);setResendCooldown(60)}catch(e){authMessage(resend?"#otp-msg":"#auth-msg",e.message||"We couldn’t send a code. Check your number and try again.");if(resend)b.disabled=false}finally{if(!resend){b.disabled=false;b.textContent="Continue"}}}
